class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;
  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];
  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      // Reload fresh data when coming back to the screen
      _initData(refresh: true);
    }
  }

  void _loadPage(int page, {bool append = false}) async {
    final currencyRepository = context.read<CurrencyRepository>();

    if (append) {
      setState(() => _isLoadingMore = true);
    }

    try {
      final CurrencyPage response = await currencyRepository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: page, pageSize: 20),
      );

      if (!mounted) return;

      setState(() {
        _currentPage = response.page + 1; // Prepare for next page
        _hasMore = response.hasMore;

        final newItems = append ? [..._allCurrencies, ...response.items] : response.items;
        _allCurrencies = newItems;
        _filteredCurrenciesNotifier.value = _filterCurrentQuery(_allCurrencies); // re-filter

        if (!append) {
          _fadeController.forward(); // only on initial load
        }

        currencyRepository.saveCurrencyList(newItems);
      });
    } catch (e) {
      // Handle error silently or show snackbar
    } finally {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  String? _currentQuery;

  List<CurrencyModel> _filterCurrentQuery(List<CurrencyModel> items, [String? query]) {
    final q = query ?? _currentQuery ?? '';
    if (q.isEmpty) return items.toList(growable: false);
    final lowerQuery = q.toLowerCase();
    return items.where((currency) => 
      currency.name.toLowerCase().contains(lowerQuery) || 
      currency.symbol.toLowerCase().contains(lowerQuery)
    ).toList(growable: false);
  }

  void _filterCurrencies(String query) {
    _currentQuery = query;
    final result = _filterCurrentQuery(_allCurrencies, query);
    _filteredCurrenciesNotifier.value = result;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_isLoadingMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index == data.length && _isLoadingMore) {
                            return const Center(child: CircularProgressIndicator());
                          }

                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
                // "Show More" button - only shown when hasMore and not loading more
                if (_hasMore && !_isLoadingMore)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 20),
                    child: ElevatedButton(
                      onPressed: () => _loadPage(_currentPage, append: true),
                      child: Text(context.loc.showMore ?? 'Show More'), // Need to check l10n
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}
```

